// Pole + pole-painting math — ported VERBATIM from SignEstimate Pro
// (NewFoundationEstimate.jsx: polesTotal / calcPolePaintingCost /
//  getPolePaintingSizeMultiplier). Poles are PROJECT-level, not per foundation item.
//
// Availability hardening: a missing price, malformed dimension, or invalid
// painting setting is not a free pole — the row is held with its acknowledged
// snapshot amounts and reported instead of silently repricing to $0.
//
// CMP-E01/O-056 consolidation: project-level `poles[]` is the single priced
// representation. The legacy per-item pole fields (`selected_pole_id`,
// `pole_total_height_inches`, `pole_offset_from_bottom_inches`, item-level
// `include_pole_painting`, and the dead `pole_cost`/`pole_painting_cost`
// snapshots) are NEVER priced — they derive advisory `legacy_item` rows via
// consolidateFoundationPoles and move onto the canonical list only through the
// explicit migrateLegacyItemPole step. A row marked pole_origin "legacy_item"
// that reaches the priced path is held, never silently repriced.
//
// CMP-E02/O-057 geometry: foundationPoleGeometry resolves five DISTINCT
// quantities that used to be conflated into height_inches + y_offset_inches —
// height above grade, embedment below grade (canonical `embedment_inches`,
// legacy `y_offset_inches` is the same quantity's old spelling), vertical base
// offset above grade (`base_offset_inches`, placement only — never material
// length), plan offset (x_inches/z_inches), and the explicit total stock
// length (`total_length_inches`, the billed length when recorded; otherwise
// the billed length is height + embedment). The actual cross-section shape
// (`pole_shape`, authored then catalog) is carried distinctly — the priced
// math below is unchanged for rows that record none of the new fields.

const assignedId = value => (typeof value === "string" && value.trim() !== "")
  || (typeof value === "number" && Number.isFinite(value));

// Inventory normalization boundary (CMP-A08): the canonical settings pick and
// price/dimension/measurement kernels live in
// masterInventory/inventoryNormalization.
//   poleSettingValue      — explicit-0-respecting pick (same semantics as wallSettingValue)
//   polePriceNumber       — catalog/customer price basis: finite, nonnegative
//                           (explicit 0 is a valid free price)
//   poleDimensionNumber   — positive finite dimension in inches/feet (height
//                           above grade, stock length, pole width)
//   poleOffsetNumber      — finite nonnegative measurement (depth in ground may
//                           legitimately be zero; negatives are not lengths)
//   poleSettingNumber / polePositiveSettingNumber — setting compositions;
//                           missing/blank settings keep the module default,
//                           recorded values must parse on the basis.
//   poleFiniteNumber      — finite signed basis (legacy field presence checks)
import {
  inventorySettingValue as poleSettingValue,
  inventoryNonnegativeNumber as polePriceNumber,
  inventoryPositiveNumber as poleDimensionNumber,
  inventoryNonnegativeMeasurement as poleOffsetNumber,
  inventorySettingNumber as poleSettingNumber,
  inventoryPositiveSettingNumber as polePositiveSettingNumber,
  inventoryFiniteNumber as poleFiniteNumber,
} from "@/components/masterInventory/inventoryNormalization";

const setting = (settings, key, def) => parseFloat(poleSettingValue(settings?.[key], def));

const POLE_PAINT_SETTING_DEFAULTS = {
  pole_paint_cost_per_lf: 3.5,
  pole_paint_labor_per_lf: 2.5,
  pole_paint_size_multiplier_12in: 2.0,
  pole_paint_size_multiplier_10in: 1.75,
  pole_paint_size_multiplier_8in: 1.5,
  pole_paint_size_multiplier_6in: 1.25,
  pole_paint_size_multiplier_4in: 1.0,
};

const polePaintMultiplierKey = (widthInches) => {
  const w = widthInches === null ? 6 : widthInches;
  if (w >= 12) return "pole_paint_size_multiplier_12in";
  if (w >= 10) return "pole_paint_size_multiplier_10in";
  if (w >= 8) return "pole_paint_size_multiplier_8in";
  if (w >= 6) return "pole_paint_size_multiplier_6in";
  return "pole_paint_size_multiplier_4in";
};

const getPolePaintingSizeMultiplier = (inv, settings) => {
  const w = inv?.pole_width_inches || 6;
  if (w >= 12) return setting(settings, "pole_paint_size_multiplier_12in", 2.0);
  if (w >= 10) return setting(settings, "pole_paint_size_multiplier_10in", 1.75);
  if (w >= 8) return setting(settings, "pole_paint_size_multiplier_8in", 1.5);
  if (w >= 6) return setting(settings, "pole_paint_size_multiplier_6in", 1.25);
  return setting(settings, "pole_paint_size_multiplier_4in", 1.0);
};

export const calcPolePaintingCost = (p, inv, settings) => {
  if (!p.include_pole_painting || !inv) return 0;
  // Total pole length = height above ground + depth in ground.
  const heightFt = ((p.height_inches || 0) + (p.y_offset_inches || 0)) / 12;
  const paintCostPerLf = setting(settings, "pole_paint_cost_per_lf", 3.5);
  const paintLaborPerLf = setting(settings, "pole_paint_labor_per_lf", 2.5);
  const sizeMult = getPolePaintingSizeMultiplier(inv, settings);
  return heightFt * (paintCostPerLf + paintLaborPerLf) * sizeMult;
};

// ─── Canonical pole geometry (CMP-E02 / O-057) ──────────────────────────────
//
// Known cross-section values; a recorded string outside this set is still
// carried verbatim (shape is geometry metadata, not yet a priced quantity) —
// only a non-string recording is malformed authored data and holds the row.
export const POLE_SHAPE_VALUES = ["round", "square", "rectangular", "elliptical", "other"];

// A recorded value is present data; undefined/null/"" are absent (blank is
// "not authored", matching the draft-input boundary).
const recorded = (v) => v !== undefined && v !== null && v !== "";

// Resolve the distinct pole quantities into one model. Returns:
//   height_above_grade_inches — pole dimension above finished grade (required)
//   embedment_inches          — depth below grade; canonical embedment_inches,
//                               legacy y_offset_inches is the same quantity
//   base_offset_inches        — pole base above grade (wall/pier mounting);
//                               placement metadata, never material length
//   plan_offset_inches        — plan position x/z (lenient finite-or-0, the
//                               same basis the layout canvas/preview consume)
//   total_length_inches       — explicit billed/purchased stock length override
//   required_length_inches    — billed material length: explicit total, else
//                               height + embedment (the unchanged ported basis)
//   pole_shape                — actual cross-section (authored > catalog), or
//                               null when unspecified — never invented
//   cross_section             — catalog width/depth/wall-thickness for shape
//   sources                   — which field supplied each quantity
//   problems                  — [{field, code, message}] for the caller to map
//                               onto held-row issues (never repriced silently)
export function foundationPoleGeometry(pole, inv = null) {
  const p = pole ?? {};
  const problems = [];
  const add = (field, code, message) => problems.push({ field, code, message });

  // Height above grade — a distinct, always-required quantity.
  const height = poleDimensionNumber(p.height_inches);
  const heightSource = height !== null ? "height_inches" : "unavailable";
  if (height === null) {
    add("height_inches", "pole_height_unavailable",
      "record a positive, finite height above grade in inches before repricing");
  }

  // Embedment below grade — canonical embedment_inches; y_offset_inches is
  // the legacy spelling of the SAME quantity (the panel labeled it "depth in
  // ground" and the priced length has always included it). Both recorded and
  // resolving differently is ambiguous authored data — held, never picked.
  const canonEmbedRaw = p.embedment_inches;
  const legacyEmbedRaw = p.y_offset_inches;
  const canonEmbedPresent = recorded(canonEmbedRaw);
  const legacyEmbedPresent = recorded(legacyEmbedRaw);
  let embedment = null;
  let embedmentSource = "unavailable";
  if (canonEmbedPresent) {
    embedment = poleOffsetNumber(canonEmbedRaw);
    if (embedment === null) {
      add("embedment_inches", "pole_embedment_unavailable",
        "record a finite, nonnegative embedment below grade in inches before repricing");
    } else {
      embedmentSource = "embedment_inches";
    }
  }
  if (legacyEmbedPresent) {
    const legacy = poleOffsetNumber(legacyEmbedRaw);
    if (!canonEmbedPresent) {
      embedment = legacy;
      if (legacy === null) {
        add("y_offset_inches", "pole_depth_unavailable",
          "record a finite, nonnegative depth in ground in inches before repricing");
      } else {
        embedmentSource = "y_offset_inches";
      }
    } else if (embedment !== null && legacy !== null && legacy !== embedment) {
      add("embedment_inches", "pole_embedment_conflict",
        "embedment and legacy depth-in-ground record different values — clear one before repricing");
    }
  }
  if (!canonEmbedPresent && !legacyEmbedPresent) {
    add("y_offset_inches", "pole_depth_unavailable",
      "record a finite, nonnegative depth in ground in inches before repricing");
  }

  // Vertical base offset — where the pole's base sits relative to grade
  // (e.g. wall-top mounting). Placement metadata only: it never contributes
  // to required material length.
  const baseRaw = p.base_offset_inches;
  let baseOffset = 0;
  let baseSource = "default";
  if (recorded(baseRaw)) {
    baseOffset = poleOffsetNumber(baseRaw);
    if (baseOffset === null) {
      add("base_offset_inches", "pole_base_offset_unavailable",
        "record a finite, nonnegative base offset above grade in inches or clear it before repricing");
    } else {
      baseSource = "base_offset_inches";
    }
  }

  // Explicit total stock length — the purchased/billed stick length. When
  // recorded it is the billed length; it must cover height + embedment or the
  // pole cannot physically reach its recorded embedment.
  const totalRaw = p.total_length_inches;
  let total = null;
  let totalSource = "derived";
  if (recorded(totalRaw)) {
    total = poleDimensionNumber(totalRaw);
    if (total === null) {
      add("total_length_inches", "pole_total_length_unavailable",
        "record a positive, finite total stock length in inches or clear it before repricing");
    } else {
      totalSource = "total_length_inches";
    }
  }

  // Billed material length — the unchanged ported basis (height + embedment)
  // unless an explicit total stock length overrides it.
  let required = null;
  if (totalSource === "total_length_inches" && total !== null) {
    required = total;
    if (height !== null && embedment !== null && total < height + embedment) {
      add("total_length_inches", "pole_total_length_conflict",
        "total stock length is shorter than height above grade plus embedment — lengthen it or clear it before repricing");
    }
  } else if (height !== null && embedment !== null) {
    required = height + embedment;
  }

  // Actual cross-section — authored pole_shape wins over the catalog row's
  // pole_shape; an unspecified shape stays null (unspecified is legitimate —
  // the renderers assume round today and no claim otherwise is made). A
  // recorded non-string is malformed authored data and holds the row.
  const authoredShapePresent = recorded(p.pole_shape);
  const shapeRaw = authoredShapePresent ? p.pole_shape : inv?.pole_shape;
  let shape = null;
  let shapeSource = null;
  let shapeKnown = false;
  if (recorded(shapeRaw)) {
    if (typeof shapeRaw !== "string") {
      add("pole_shape", "pole_shape_unavailable",
        "recorded pole shape must be a value like round or square — clear or correct it before repricing");
    } else {
      shape = shapeRaw.trim().toLowerCase();
      shapeSource = authoredShapePresent ? "pole_shape" : "catalog";
      shapeKnown = POLE_SHAPE_VALUES.includes(shape);
    }
  }
  const cross_section = inv == null ? null : {
    shape,
    width_inches: poleOffsetNumber(inv.pole_width_inches),
    depth_inches: poleOffsetNumber(inv.pole_depth_inches),
    wall_thickness_inches: poleOffsetNumber(inv.pole_wall_thickness_inches),
  };

  // Plan offset — the same finite-or-0 basis the layout canvas and preview
  // consume (placement only, never material length).
  const planOffset = {
    x_inches: poleFiniteNumber(p.x_inches) ?? 0,
    z_inches: poleFiniteNumber(p.z_inches) ?? 0,
  };

  return {
    height_above_grade_inches: height,
    embedment_inches: embedment,
    base_offset_inches: baseOffset,
    plan_offset_inches: planOffset,
    total_length_inches: total,
    required_length_inches: required,
    pole_shape: shape,
    pole_shape_known: shapeKnown,
    cross_section,
    sources: {
      height_above_grade: heightSource,
      embedment: embedmentSource,
      base_offset: baseSource,
      total_length: totalSource,
      shape: shapeSource,
    },
    problems,
  };
}

// ─── Legacy item-pole consolidation (CMP-E01 / O-056) ───────────────────────
//
// The single priced representation is project.poles. Item rows can still carry
// the pre-CMP fields below; they are ghost data (rendered in the 3D preview,
// never priced — item_total_cost has no pole term and sumPole reads only
// project poles). These helpers expose them as advisory derived rows and move
// them onto the canonical list only through the explicit migrate step, so a
// physical pole is never billed twice and never silently loses geometry.
export const POLE_ORIGIN_PROJECT = "project";
export const POLE_ORIGIN_LEGACY_ITEM = "legacy_item";
export const LEGACY_ITEM_POLE_FIELDS = [
  "selected_pole_id", "pole_total_height_inches", "pole_offset_from_bottom_inches",
  "include_pole_painting",
];

const isCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// An item "carries" a legacy pole when any pole field departs from the
// blankItem defaults — including the dead pole_cost/pole_painting_cost
// snapshots, which prove a pole once existed even if the selection was lost.
export function itemHasLegacyPole(item) {
  if (!item || typeof item !== "object") return false;
  const id = item.selected_pole_id;
  if (assignedId(id)) return true;
  const height = poleFiniteNumber(item.pole_total_height_inches);
  if (height !== null && height !== 0) return true;
  const offBottom = poleFiniteNumber(item.pole_offset_from_bottom_inches);
  if (offBottom !== null && offBottom !== 0) return true;
  if (item.include_pole_painting === true) return true;
  if (isCostSnapshot(item.pole_cost) || isCostSnapshot(item.pole_painting_cost)) return true;
  return false;
}

// Advisory derived view of one item's legacy pole fields — marked
// pole_origin "legacy_item" so it can never enter the priced list silently.
// `height_inches` is null when the legacy total height is absent/malformed;
// embedment is intentionally absent (not derivable — see migrate below).
export function deriveLegacyItemPole(item, index = 0) {
  if (!itemHasLegacyPole(item)) return null;
  const height = poleFiniteNumber(item.pole_total_height_inches);
  const offBottom = poleFiniteNumber(item.pole_offset_from_bottom_inches);
  return {
    pole_origin: POLE_ORIGIN_LEGACY_ITEM,
    source_item_index: index,
    source_item_component_id: item.component_id ?? null,
    foundation_component_id: item.component_id ?? "",
    foundation_idx: index,
    pole_id: assignedId(item.selected_pole_id) ? item.selected_pole_id : "",
    height_inches: height !== null && height > 0 ? height : null,
    include_pole_painting: item.include_pole_painting === true,
    legacy_pole_offset_from_bottom_inches: offBottom,
    legacy_pole_cost: isCostSnapshot(item.pole_cost) ? item.pole_cost : null,
    legacy_pole_painting_cost: isCostSnapshot(item.pole_painting_cost) ? item.pole_painting_cost : null,
  };
}

// Consolidated pole model for one project (or any {items, poles} source):
//   poles       — the canonical, priced list (same row refs, never mutated)
//   legacyPoles — advisory rows derived from item-level fields
//   overlaps    — [{derivedIndex, poleIndex, ...}] where a project pole is
//                 already assigned to the same foundation; surfaced for review
//                 rather than silently deduplicated (two poles on one footing
//                 are legitimate)
//   issues      — advisory-only; `severity: "advisory"` keeps them out of the
//                 priced-issue channels that gate save/handoff
export function consolidateFoundationPoles(source = {}) {
  const items = Array.isArray(source?.items) ? source.items : [];
  const poles = Array.isArray(source?.poles) ? source.poles : [];
  const legacyPoles = [];
  const overlaps = [];
  const issues = [];
  items.forEach((item, index) => {
    const derived = deriveLegacyItemPole(item, index);
    if (!derived) return;
    const derivedIndex = legacyPoles.length;
    legacyPoles.push(derived);
    issues.push({
      kind: "pole", severity: "advisory", code: "legacy_item_pole_fields",
      componentId: item?.component_id ?? null, field: "selected_pole_id",
      message: `Foundation ${index + 1} carries legacy item-pole fields that are not priced — migrate them into the Poles section or clear them.`,
    });
    poles.forEach((p, poleIndex) => {
      // Overlap = this project pole is assigned to this foundation item —
      // by component id when both sides carry one, otherwise by the
      // foundation_idx slot (which is itself an assignment signal even when
      // the component id side is missing).
      const assignedToItem = p?.foundation_component_id && item?.component_id
        ? p.foundation_component_id === item.component_id
        : p?.foundation_idx !== undefined && p?.foundation_idx !== null
          && p.foundation_idx === index;
      if (assignedToItem) {
        overlaps.push({
          derivedIndex, poleIndex,
          itemComponentId: item?.component_id ?? null,
          poleComponentId: p?.component_id ?? null,
        });
      }
    });
  });
  const overlappedItems = new Set(overlaps.map((o) => o.derivedIndex));
  for (const derivedIndex of overlappedItems) {
    const count = overlaps.filter((o) => o.derivedIndex === derivedIndex).length;
    const itemIndex = legacyPoles[derivedIndex]?.source_item_index ?? derivedIndex;
    issues.push({
      kind: "pole", severity: "advisory", code: "pole_representation_overlap",
      componentId: legacyPoles[derivedIndex]?.source_item_component_id ?? null,
      field: "selected_pole_id",
      message: `Foundation ${itemIndex + 1} has legacy item-pole fields and ${count} project pole(s) on the same foundation — verify they describe different physical poles before migrating.`,
    });
  }
  return { poles, legacyPoles, overlaps, issues };
}

// The explicit consolidation step: build the canonical project-pole row from
// an item's legacy fields plus the patch that clears them. The returned pole
// deliberately leaves embedment unrecorded — pole_offset_from_bottom_inches is
// ambiguous (offset above the footing bottom, not a depth in ground), so it is
// preserved verbatim as legacy_pole_offset_from_bottom_inches and the priced
// row holds on pole_depth_unavailable until a real embedment is recorded.
// Plan position inherits the foundation item's recorded x/z placement.
export function migrateLegacyItemPole(item, index = 0, { createId } = {}) {
  if (!itemHasLegacyPole(item)) return null;
  const height = poleFiniteNumber(item.pole_total_height_inches);
  const offBottom = poleFiniteNumber(item.pole_offset_from_bottom_inches);
  const planX = poleFiniteNumber(item.x_inches);
  const planZ = poleFiniteNumber(item.z_inches);
  const pole = {
    ...(typeof createId === "function" ? { component_id: createId("pole") } : {}),
    pole_id: assignedId(item.selected_pole_id) ? item.selected_pole_id : "",
    ...(height !== null && height > 0 ? { height_inches: height } : {}),
    include_pole_painting: item.include_pole_painting === true,
    foundation_component_id: item.component_id ?? "",
    foundation_idx: index,
    ...(planX !== null ? { x_inches: planX } : {}),
    ...(planZ !== null ? { z_inches: planZ } : {}),
    migrated_from: POLE_ORIGIN_LEGACY_ITEM,
    source_item_component_id: item.component_id ?? undefined,
    ...(offBottom !== null ? { legacy_pole_offset_from_bottom_inches: offBottom } : {}),
  };
  const itemPatch = {
    selected_pole_id: "",
    pole_total_height_inches: 0,
    pole_offset_from_bottom_inches: 0,
    include_pole_painting: false,
    // The dead item-level snapshots clear too — leaving them would keep the
    // item flagged as carrying a legacy pole after its explicit migration.
    pole_cost: undefined,
    pole_painting_cost: undefined,
  };
  return { pole, itemPatch };
}

// Resolves the catalog row and every value the pricing formulas read, on a
// normalized calculation copy — authored rows and settings are never mutated.
function polePricing(pole, inventory = [], index = 0, settings = {}) {
  const issues = [];
  const id = pole?.pole_id;
  const paint = { costPerLf: null, laborPerLf: null, sizeMultiplier: null };
  const add = (field, code, message) => issues.push({
    kind: "pole", index, componentId: pole?.component_id ?? pole?.id ?? null,
    field, inventoryId: assignedId(id) ? id : null, code,
    message: `Pole ${index + 1}: ${message}.`,
  });
  // Fail closed on the legacy representation: a row marked legacy_item must
  // never reach the priced list — migrate it through migrateLegacyItemPole or
  // it stays held (a silent price here would double-charge the ghost pole).
  if (pole?.pole_origin === POLE_ORIGIN_LEGACY_ITEM) {
    add("pole_origin", "pole_legacy_representation",
      "legacy item-pole data cannot price here — migrate it into the Poles section or remove it");
    return { issues, inv: null, geometry: null, painting: false, rate: null, stockLengthInches: null, widthInches: null, paint };
  }
  let inv = null;
  if (!assignedId(id)) {
    add("pole_id", "catalog_item_unassigned", "select a catalog material");
  } else {
    const matches = inventory.filter((row) => row?.id === id);
    if (!matches.length) {
      add("pole_id", "catalog_item_unavailable", "selected catalog material is unavailable");
    } else if (matches.length !== 1) {
      add("pole_id", "catalog_item_ambiguous", "selected catalog material is ambiguous");
    } else if (matches[0].material_type !== "pole") {
      add("pole_id", "catalog_item_type_mismatch", "selected catalog material is not a pole");
    } else {
      inv = matches[0];
    }
  }
  // Distinct authored/calculated quantities (CMP-E02). The height and
  // depth-in-ground checks map onto the geometry problems unchanged — same
  // codes and messages as the pre-consolidation checks.
  const geometry = foundationPoleGeometry(pole, inv);
  for (const problem of geometry.problems) add(problem.field, problem.code, problem.message);
  const painting = pole?.include_pole_painting === true;
  let rate = null;
  let stockLengthInches = null;
  let widthInches = null;
  if (inv) {
    const override = pole?.custom_cost_per_unit;
    const hasOverride = override !== undefined && override !== null;
    const stockMode = inv.pole_pricing_mode === "stock_price";
    rate = polePriceNumber(hasOverride ? override : (stockMode ? inv.pole_stock_price : inv.cost_per_unit));
    if (rate === null) {
      add(hasOverride ? "custom_cost_per_unit" : stockMode ? "pole_stock_price" : "cost_per_unit",
        "pole_price_unavailable", "record a finite, nonnegative pole price before repricing");
    }
    if (stockMode) {
      const stockLengthFt = polePositiveSettingNumber(inv.pole_stock_length_ft, 20);
      if (stockLengthFt === null) {
        add("pole_stock_length_ft", "pole_stock_length_unavailable",
          "the selected catalog stock length must be a recorded finite positive number");
      } else {
        stockLengthInches = stockLengthFt * 12;
      }
    }
    if (painting) {
      widthInches = polePositiveSettingNumber(inv.pole_width_inches, 6);
      if (widthInches === null) {
        add("pole_width_inches", "pole_width_unavailable",
          "the selected catalog pole width must be a recorded finite positive number");
      }
      const paintSetting = (key, label) => {
        const value = poleSettingNumber(settings?.[key], POLE_PAINT_SETTING_DEFAULTS[key]);
        if (value === null) {
          add(key, "pole_paint_setting_unavailable",
            `record a finite, nonnegative ${label} before repricing`);
        }
        return value;
      };
      paint.costPerLf = paintSetting("pole_paint_cost_per_lf", "pole paint cost per LF");
      paint.laborPerLf = paintSetting("pole_paint_labor_per_lf", "pole paint labor per LF");
      paint.sizeMultiplier = paintSetting(polePaintMultiplierKey(widthInches), "pole paint size multiplier");
    }
  }
  return { issues, inv, geometry, painting, rate, stockLengthInches, widthInches, paint };
}

export function foundationPolePricingIssues(pole, inventory = [], index = 0, settings = {}) {
  return polePricing(pole, inventory, index, settings).issues;
}

export function foundationPoleCatalogIssues(poles = [], inventory = [], settings = {}) {
  return (poles || []).flatMap((pole, index) => foundationPolePricingIssues(pole, inventory, index, settings));
}

export function calcPoles(poles = [], inventory = [], settings = {}, options = {}) {
  const explicitSnapshot = options != null && Object.prototype.hasOwnProperty.call(options, "savedPoles");
  const savedPoles = Array.isArray(options?.savedPoles) ? options.savedPoles : [];
  const counts = rows => {
    const out = new Map();
    for (const row of rows) {
      const id = row?.component_id;
      if (assignedId(id)) out.set(id, (out.get(id) || 0) + 1);
    }
    return out;
  };
  const currentCounts = counts(poles), savedCounts = counts(savedPoles);
  const savedById = new Map(savedPoles.filter((row) => assignedId(row?.component_id))
    .map((row) => [row.component_id, row]));
  // Preserve the last saved amounts, not a fabricated free pole. The project
  // availability gate prevents these historical values becoming a new quote.
  const held = pole => {
    const id = pole?.component_id;
    const acknowledged = explicitSnapshot
      ? assignedId(id) && currentCounts.get(id) === 1 && savedCounts.get(id) === 1
        ? savedById.get(id) : null
      : pole;
    const result = { ...pole };
    if (explicitSnapshot) {
      // Calculated snapshot fields only — authored fields ride on the spread.
      for (const field of ["pole_name", "pole_cost", "pole_painting_cost", "total_cost",
        "required_length_inches", "stock_pieces"]) {
        if (acknowledged && Object.prototype.hasOwnProperty.call(acknowledged, field)) result[field] = acknowledged[field];
        else delete result[field];
      }
    }
    return result;
  };
  const results = (poles || []).map((pole, index) => polePricing(pole, inventory, index, settings));
  return {
    poles: results.map((check, index) => {
      const pole = poles[index];
      if (check.issues.length) return held(pole);
      const { inv, geometry, rate, stockLengthInches, widthInches, paint } = check;
      const requiredInches = geometry.required_length_inches;
      let poleCost;
      let stockPieces = null;
      if (inv.pole_pricing_mode === "stock_price") {
        stockPieces = Math.ceil(requiredInches / stockLengthInches);
        poleCost = stockPieces * rate;
      } else {
        poleCost = (requiredInches / 12) * rate;
      }
      // The guarded path reuses the ported painting math on the normalized
      // calculation copy, so valid inputs price identically to the original.
      // The painted length is the billed required length — the whole stick.
      const paintingCost = check.painting
        ? calcPolePaintingCost(
            { include_pole_painting: true, height_inches: requiredInches, y_offset_inches: 0 },
            { ...inv, pole_width_inches: widthInches },
            {
              pole_paint_cost_per_lf: paint.costPerLf,
              pole_paint_labor_per_lf: paint.laborPerLf,
              [polePaintMultiplierKey(widthInches)]: paint.sizeMultiplier,
            })
        : 0;
      return {
        ...pole,
        // Resolved-geometry snapshots (CMP-E02): the canonical embedment
        // materializes alongside the authored legacy spelling; required
        // length, stock pieces, base offset and resolved shape persist so the
        // BOM, preview and handoff read the same distinct quantities.
        embedment_inches: geometry.embedment_inches,
        base_offset_inches: geometry.base_offset_inches,
        required_length_inches: requiredInches,
        stock_pieces: stockPieces,
        ...(geometry.pole_shape !== null ? { pole_shape: geometry.pole_shape } : {}),
        pole_name: inv.material_name || "",
        pole_cost: poleCost,
        pole_painting_cost: paintingCost,
        total_cost: poleCost + paintingCost,
      };
    }),
    polePricing: results.map((check) => ({
      available: check.issues.length === 0,
      issues: check.issues,
      // Resolved canonical geometry for display surfaces (never priced again).
      geometry: check.geometry,
    })),
  };
}

// Ported verbatim from SignEstimate Pro (src/utils/wallCalculator.js).
// Do not re-derive this math — outer wall + optional internal (fill) wall
// brick counts, mortar bags, labor and totals.
//
// Residual-input hardening: a malformed mortar gap, override quantity/rate, or
// wall labor setting is not a free or negative wall — the row is held with its
// acknowledged snapshot amounts and reported instead of silently repricing to
// $0 or producing negative/NaN quantities.

// Inventory normalization boundary (CMP-A08): the canonical settings pick,
// price/dimension kernels and their setting compositions live in
// masterInventory/inventoryNormalization. CMP-D03 adds the canonical wall
// material subtype classifier — brick/CMU/stone are unit masonry priced by
// unit count, `concrete` is poured concrete priced by placed volume (CY).
import {
  inventorySettingValue as wallSettingValue,
  inventoryNonnegativeNumber as wallPriceNumber,
  inventoryPositiveNumber as wallDimensionNumber,
  inventorySettingNumber as wallSettingNumber,
  inventoryPositiveSettingNumber as wallPositiveSettingNumber,
  canonicalWallMaterialSubtype,
  wallMaterialSubtypeRecorded,
} from "@/components/masterInventory/inventoryNormalization";

// 36³ in³ per cubic yard — the poured-concrete wall quantity conversion.
const CUBIC_INCHES_PER_CUBIC_YARD = 46656;

// Recorded `unit` spellings accepted as the cubic-yard cost basis on a
// poured-concrete catalog row. A blank unit keeps the catalog's implicit
// $/CY basis; any OTHER recorded unit is an unresolved price-basis ambiguity
// the check reports rather than guessing (never silently repriced wrong).
const POURED_CONCRETE_UNIT_BASIS = new Set([
  "cy", "cyd", "cy_d", "yd", "yd3", "cu_yd", "cubic_yard", "cubic_yards", "yard", "yards",
]);

export function calcWallCosts({ wall, wallShape, wallMaterial, internalMaterial, includeInternalWall, wallHeightInches, internalWallHeightInches, mortarGapInches, internalMortarGapInches, settings }) {
  if (!wallShape || !wallMaterial || !wallShape.segments) return null;

  // CMP-D03: the canonical subtype picks the quantity method. Unit masonry
  // (brick / cinderblock / stone) counts units from cataloged unit dimensions;
  // `concrete` is poured — its material quantity is the placed volume in
  // cubic yards (outline perimeter x wall height x cataloged wall thickness),
  // with no courses, mortar joints, or per-unit production-hours basis.
  const isConcrete = canonicalWallMaterialSubtype(wallMaterial.wall_material_subtype) === 'concrete';
  const unitL = wallMaterial.wall_unit_length_inches || 8;
  const unitW = wallMaterial.wall_unit_width_inches || 4;
  const unitH = wallMaterial.wall_unit_height_inches || 2.25;
  const mortar = isConcrete ? 0 : mortarGapInches;
  const courseH = unitH + mortar;
  const numCourses = isConcrete ? 0 : wallHeightInches / courseH;
  const brickPitch = unitL + (isConcrete ? 0 : mortar);

  const totalLinearInches = wallShape.segments.reduce((s, seg) => s + seg.length, 0);

  let totalBricks = 0;
  if (isConcrete) {
    // Poured concrete — distinct quantity method: volume of the placed wall.
    totalBricks = (totalLinearInches * wallHeightInches * unitW) / CUBIC_INCHES_PER_CUBIC_YARD;
  } else {
    const numCoursesRounded = Math.ceil(numCourses);
    wallShape.segments.forEach(seg => {
      const bricksThisCourse = Math.ceil(seg.length / brickPitch);
      totalBricks += bricksThisCourse * numCoursesRounded;
    });
  }

  const finalBricks = wallMaterial.custom_outer_material_qty !== undefined && wallMaterial.custom_outer_material_qty !== null ? wallMaterial.custom_outer_material_qty : totalBricks;
  const materialCost = finalBricks * (wallMaterial.custom_cost_per_unit !== undefined && wallMaterial.custom_cost_per_unit !== null ? wallMaterial.custom_cost_per_unit : (wallMaterial.cost_per_unit || 0));

  const surfaceAreaSqFtSingleSide = (totalLinearInches * wallHeightInches) / 144;

  let mortarCost = 0;
  let mortarBags = 0;
  if (!isConcrete) {
    const surfaceAreaSqFtMortar = surfaceAreaSqFtSingleSide * 2;
    mortarBags = Math.ceil(surfaceAreaSqFtMortar / 30);
    const finalMortarBags = wallMaterial.custom_outer_mortar_qty !== undefined && wallMaterial.custom_outer_mortar_qty !== null ? wallMaterial.custom_outer_mortar_qty : mortarBags;
    const mortarCostPerBag = parseFloat(wallSettingValue(settings?.wall_mortar_cost_per_bag, 10));
    const finalMortarRate = wallMaterial.custom_outer_mortar_rate !== undefined && wallMaterial.custom_outer_mortar_rate !== null ? wallMaterial.custom_outer_mortar_rate : mortarCostPerBag;
    mortarCost = finalMortarBags * finalMortarRate;
  }

  const laborRatePerSqFt = wallMaterial.custom_outer_labor_rate !== undefined && wallMaterial.custom_outer_labor_rate !== null ? wallMaterial.custom_outer_labor_rate : parseFloat(wallSettingValue(settings?.wall_labor_rate, 45));
  const minCharge = parseFloat(wallSettingValue(settings?.wall_minimum_charge, 150));

  let laborCost = surfaceAreaSqFtSingleSide * laborRatePerSqFt;
  if (laborCost < minCharge) {
    laborCost = minCharge;
  }

  // Poured work is priced by wall-face area (laborCost) — there is no
  // per-unit production-hours basis to divide by, so hours stay 0 rather than
  // minting a fictitious bricks-per-hour figure on a CY quantity.
  const laborHours = isConcrete ? 0 : finalBricks / (parseFloat(wallSettingValue(settings?.wall_labor_bricks_per_hour, 50)));

  // --- Internal Wall Calculation ---
  let internalTotalBricks = 0;
  let internalMaterialCost = 0;
  let internalMortarCost = 0;
  let internalLaborCost = 0;
  let internalLaborHours = 0;
  let internalTotalLinearInches = 0;
  let intIsConcrete = false;

  if (includeInternalWall && internalMaterial) {
    intIsConcrete = canonicalWallMaterialSubtype(internalMaterial.wall_material_subtype) === 'concrete';
    const intUnitL = internalMaterial.wall_unit_length_inches || 8;
    const intUnitW = internalMaterial.wall_unit_width_inches || 4;
    const intUnitH = internalMaterial.wall_unit_height_inches || 2.25;
    const intMortar = intIsConcrete ? 0 : (internalMortarGapInches ?? 0.375);
    const intCourseH = intUnitH + intMortar;
    const intNumCourses = Math.ceil(internalWallHeightInches / intCourseH);
    const intBrickPitch = intUnitL + intMortar;

    const isClosed = wallShape.closed !== false;
    const lengthReduction = isClosed ? (unitW + intUnitW) : 0;

    wallShape.segments.forEach(seg => {
      const innerSegLength = Math.max(0, seg.length - lengthReduction);
      internalTotalLinearInches += innerSegLength;

      // Poured internal fill prices by placed volume too — same CY method as
      // the outer wall; unit masonry keeps the per-course unit count.
      if (intIsConcrete) {
        internalTotalBricks += (innerSegLength * internalWallHeightInches * intUnitW) / CUBIC_INCHES_PER_CUBIC_YARD;
      } else {
        const bricksThisCourse = Math.ceil(innerSegLength / intBrickPitch);
        internalTotalBricks += bricksThisCourse * intNumCourses;
      }
    });

    const finalInternalBricks = wall.custom_internal_material_qty !== undefined && wall.custom_internal_material_qty !== null ? wall.custom_internal_material_qty : internalTotalBricks;
    internalMaterialCost = finalInternalBricks * (wall.custom_internal_material_cost_per_unit !== undefined && wall.custom_internal_material_cost_per_unit !== null ? wall.custom_internal_material_cost_per_unit : (internalMaterial.cost_per_unit || 0));

    const intSurfaceAreaSqFtSingleSide = (internalTotalLinearInches * internalWallHeightInches) / 144;

    let internalMortarBags = 0;
    if (!intIsConcrete) {
      const intSurfaceAreaSqFtMortar = intSurfaceAreaSqFtSingleSide * 2;
      internalMortarBags = Math.ceil(intSurfaceAreaSqFtMortar / 30);
      const finalInternalMortarBags = wall.custom_internal_mortar_qty !== undefined && wall.custom_internal_mortar_qty !== null ? wall.custom_internal_mortar_qty : internalMortarBags;
      const internalMortarCostPerBag = parseFloat(wallSettingValue(settings?.wall_mortar_cost_per_bag, 10));
      const finalInternalMortarRate = wall.custom_internal_mortar_rate !== undefined && wall.custom_internal_mortar_rate !== null ? wall.custom_internal_mortar_rate : internalMortarCostPerBag;
      internalMortarCost = finalInternalMortarBags * finalInternalMortarRate;
    }

    const internalLaborRatePerSqFt = wall.custom_internal_labor_rate !== undefined && wall.custom_internal_labor_rate !== null ? wall.custom_internal_labor_rate : parseFloat(wallSettingValue(settings?.wall_labor_rate, 45));
    internalLaborCost = intSurfaceAreaSqFtSingleSide * internalLaborRatePerSqFt;
    internalLaborHours = intIsConcrete ? 0
      : finalInternalBricks / (parseFloat(wallSettingValue(settings?.wall_labor_bricks_per_hour, 50)));
  }

  return {
    totalBricks,
    finalBricks,
    materialCost,
    mortarBags,
    finalMortarBags: !isConcrete ? (wallMaterial.custom_outer_mortar_qty !== undefined && wallMaterial.custom_outer_mortar_qty !== null ? wallMaterial.custom_outer_mortar_qty : mortarBags) : 0,
    mortarCost,
    laborHours,
    laborRatePerSqFt,
    laborCost,
    totalCost: materialCost + mortarCost + laborCost + internalMaterialCost + internalMortarCost + internalLaborCost,
    totalLinearInches,
    numCourses,
    internalTotalBricks,
    internalMaterialCost,
    internalMortarBags: includeInternalWall && internalMaterial && !intIsConcrete ? Math.ceil(((internalTotalLinearInches * internalWallHeightInches) / 144) * 2 / 30) : 0,
    internalMortarCost,
    internalLaborCost,
    internalLaborHours
  };
}

const assignedId = value => (typeof value === "string" && value.trim() !== "")
  || (typeof value === "number" && Number.isFinite(value));

// Missing/blank settings fall back to the module default; present values must be
// finite nonnegative numbers (explicit 0 honored — a genuinely free rate).
// wallSettingNumber / wallPositiveSettingNumber are boundary aliases (rates
// that are meaningless at zero — production speed — must be finite positive).

// Blank/absent mortar gaps keep the ported 3/8" default; a recorded gap must be
// finite nonnegative — explicit 0 is a legitimate stack-bond joint.
const WALL_MORTAR_GAP_DEFAULT = 0.375;
const wallMortarGapNumber = (value) => value === undefined || value === null || value === ""
  ? WALL_MORTAR_GAP_DEFAULT : wallPriceNumber(value);

const wallRecord = value => !!value && typeof value === "object" && !Array.isArray(value);
const wallPoint = point => wallRecord(point)
  && typeof point.x === "number" && Number.isFinite(point.x)
  && typeof point.z === "number" && Number.isFinite(point.z);

export function foundationWallSegments(points, closed = false) {
  if (!Array.isArray(points) || !points.every(wallPoint) || typeof closed !== "boolean") return null;
  const segments = [];
  const add = (a, b) => segments.push({ length: Math.hypot(b.x - a.x, b.z - a.z) });
  for (let i = 0; i < points.length - 1; i++) add(points[i], points[i + 1]);
  if (closed && points.length > 2) add(points[points.length - 1], points[0]);
  return segments.every(segment => Number.isFinite(segment.length)) ? segments : null;
}

export function foundationWallOutlineBasis(shape) {
  const result = {
    shape: null, points: [], closed: shape?.closed === true,
    hasRecordedPoints: false, perimeterInches: null, issues: [],
  };
  const add = (code, message) => result.issues.push({ code, message });
  const unavailable = () => add("wall_outline_unavailable", "draw an outline with positive segment lengths before repricing");
  if (!wallRecord(shape)) { unavailable(); return result; }
  result.hasRecordedPoints = shape.points != null
    && (!Array.isArray(shape.points) || shape.points.length > 0);
  const validPoints = Array.isArray(shape.points) && shape.points.every(wallPoint);
  if (validPoints) result.points = shape.points.map(point => ({ ...point }));
  if (result.hasRecordedPoints && !validPoints) {
    add("wall_outline_points_unavailable", "repair the recorded footprint coordinates before repricing");
  }
  if ((shape.closed != null || result.hasRecordedPoints) && typeof shape.closed !== "boolean") {
    add("wall_outline_closure_unavailable", "record whether the outline is open or closed before repricing");
  }
  let segments = null;
  if (!Array.isArray(shape.segments) || !shape.segments.length) {
    unavailable();
  } else {
    const lengths = shape.segments.map(segment => wallRecord(segment) ? wallDimensionNumber(segment.length) : null);
    if (lengths.some(length => length === null)) {
      add("wall_outline_segment_unavailable", "record positive, finite segment lengths in inches before repricing");
    } else {
      segments = shape.segments.map((segment, index) => ({ ...segment, length: lengths[index] }));
      if (!Number.isFinite(lengths.reduce((sum, length) => sum + length, 0))) {
        add("wall_outline_length_unavailable", "record a finite outline perimeter before repricing");
      }
    }
  }
  if (segments && result.hasRecordedPoints && validPoints && typeof shape.closed === "boolean") {
    const expected = foundationWallSegments(result.points, shape.closed);
    const same = result.points.length >= (shape.closed ? 3 : 2)
      && expected && expected.length === segments.length && expected.every((segment, index) => {
        const stored = segments[index].length;
        const tolerance = Number.EPSILON * 8 * Math.max(1, segment.length, stored);
        return segment.length > 0 && Math.abs(segment.length - stored) <= tolerance;
      });
    if (!same) add("wall_outline_geometry_mismatch", "repair footprint points and segment lengths so they describe the same outline before repricing");
  }
  if (!result.issues.length) {
    result.shape = { ...shape, segments };
    if (validPoints) result.shape.points = result.points;
    result.perimeterInches = segments.reduce((sum, segment) => sum + segment.length, 0);
  }
  return result;
}

export function foundationWallRectangle(length, width) {
  const l = wallDimensionNumber(length), w = wallDimensionNumber(width);
  if (l === null || w === null) return null;
  const points = [{ x: 0, z: 0 }, { x: l, z: 0 }, { x: l, z: w }, { x: 0, z: w }];
  return foundationWallOutlineBasis({ points, closed: true, segments: foundationWallSegments(points, true) }).shape;
}

const WALL_SETTING_DEFAULTS = {
  wall_mortar_cost_per_bag: 10,
  wall_labor_rate: 45,
  wall_minimum_charge: 150,
  wall_labor_bricks_per_hour: 50,
};
const WALL_OUTER_OVERRIDE_FIELDS = [
  ["custom_outer_material_qty", "material quantity"],
  ["custom_outer_labor_rate", "labor rate"],
];
const WALL_OUTER_MORTAR_OVERRIDE_FIELDS = [
  ["custom_outer_mortar_qty", "mortar quantity"],
  ["custom_outer_mortar_rate", "mortar rate"],
];
const WALL_INTERNAL_OVERRIDE_FIELDS = [
  ["custom_internal_material_qty", "material quantity"],
  ["custom_internal_labor_rate", "labor rate"],
];
const WALL_INTERNAL_MORTAR_OVERRIDE_FIELDS = [
  ["custom_internal_mortar_qty", "mortar quantity"],
  ["custom_internal_mortar_rate", "mortar rate"],
];

function wallPricing(wall, inventory = [], index = 0, settings = {}) {
  const issues = [];
  const heightInches = wallDimensionNumber(wall?.heightInches);
  const internalWallHeightInches = wall?.includeInternalWall
    ? wallDimensionNumber(wall.internalWallHeightInches ?? wall.heightInches) : null;
  const heightIssue = (field, kind, label, code) => issues.push({
    kind, index, componentId: wall?.component_id ?? wall?.id ?? null,
    field, inventoryId: wall?.[kind === "wall" ? "materialId" : "internalMaterialId"] ?? null, code,
    message: `${label} ${index + 1}: record a positive, finite wall height in inches before repricing.`,
  });
  if (heightInches === null) heightIssue("heightInches", "wall", "Wall", "wall_height_unavailable");
  if (wall?.includeInternalWall && internalWallHeightInches === null) {
    heightIssue("internalWallHeightInches", "internal_wall", "Internal wall", "internal_wall_height_unavailable");
  }
  const outline = foundationWallOutlineBasis(wall?.shape);
  issues.push(...outline.issues.map(issue => ({
    ...issue, kind: "wall", index, componentId: wall?.component_id ?? wall?.id ?? null,
    field: "shape", inventoryId: wall?.materialId ?? null,
    message: `Wall ${index + 1}: ${issue.message}.`,
  })));
  const check = (field, kind, label) => {
    const id = wall?.[field];
    const add = (code, message) => issues.push({
      kind, index, componentId: wall?.component_id ?? wall?.id ?? null,
      field, inventoryId: assignedId(id) ? id : null, code,
      message: `${label} ${index + 1}: ${message}.`,
    });
    if (!assignedId(id)) {
      add("catalog_item_unassigned", "select a catalog material");
      return null;
    }
    const matches = inventory.filter(row => row?.id === id);
    if (!matches.length) {
      add("catalog_item_unavailable", "selected catalog material is unavailable");
      return null;
    }
    if (matches.length !== 1) {
      add("catalog_item_ambiguous", "selected catalog material is ambiguous");
      return null;
    }
    const material = matches[0];
    if (!["brick_stone", "wall_material"].includes(material.material_type)) {
      add("catalog_item_type_mismatch", "selected catalog material is not a wall material");
      return null;
    }
    const override = kind === "wall"
      ? material.custom_cost_per_unit
      : wall.custom_internal_material_cost_per_unit;
    const price = override !== undefined && override !== null ? override : material.cost_per_unit;
    if (wallPriceNumber(price) === null) {
      add("wall_material_price_unavailable", "record a finite, nonnegative material unit price before repricing");
    }
    // CMP-D03: the recorded subtype picks the quantity method. Absent or blank
    // keeps the legacy unit-masonry default (brick_stone rows never carried a
    // subtype); a recorded-but-unrecognized subtype is held — pouring concrete
    // spelled off-enum must never silently price as mortared unit masonry, and
    // an unknown material family must never be guessed concrete either.
    const subtype = canonicalWallMaterialSubtype(material.wall_material_subtype);
    if (wallMaterialSubtypeRecorded(material.wall_material_subtype) && subtype === null) {
      add("wall_material_subtype_unavailable",
        "record a supported wall material subtype (brick, cinderblock / CMU, stone, or poured concrete) before repricing");
      return null;
    }
    const pouredConcrete = subtype === "concrete";
    // A poured row's cost basis is $/CY. A blank unit keeps that basis; any
    // OTHER recorded unit is a real price-basis ambiguity — hold it rather
    // than multiply cubic yards by a per-each price.
    if (pouredConcrete) {
      const recordedUnit = material.unit;
      const unitRecorded = recordedUnit !== undefined && recordedUnit !== null
        && (typeof recordedUnit !== "string" || recordedUnit.trim() !== "");
      if (unitRecorded) {
        const unitKey = typeof recordedUnit === "string"
          ? recordedUnit.trim().toLowerCase().replace(/[\s\-_.]+/g, "_").replace(/^_+|_+$/g, "")
          : String(recordedUnit);
        if (!POURED_CONCRETE_UNIT_BASIS.has(unitKey)) {
          add("wall_material_unit_mismatch",
            "poured concrete is priced per cubic yard — record the unit as CY (or clear it) so the cost basis is unambiguous before repricing");
        }
      }
    }
    const normalizedMaterial = { ...material };
    // The canonical subtype spelling rides the calculation copy so the
    // strict `=== 'concrete'` reads below stay exact even when this row was
    // classified from a recorded alias ("poured concrete", "cmu").
    if (subtype !== null) normalizedMaterial.wall_material_subtype = subtype;
    // Poured concrete has no unit length/height — a wall's face dimensions
    // come from the authored outline and height; the only cataloged
    // dimension is the wall thickness it is poured to (unit width field).
    for (const [key, label] of (pouredConcrete
      ? [["wall_unit_width_inches", "wall thickness"]]
      : [["wall_unit_length_inches", "unit length"], ["wall_unit_width_inches", "unit width"], ["wall_unit_height_inches", "unit height"]])) {
      const dimension = wallDimensionNumber(material[key]);
      if (dimension === null) {
        add(key + "_unavailable", `record a positive, finite ${label} in inches before repricing`);
      } else {
        normalizedMaterial[key] = dimension;
      }
    }
    return normalizedMaterial;
  };
  const wallMaterial = check("materialId", "wall", "Wall");
  const internalMaterial = wall?.includeInternalWall
    ? check("internalMaterialId", "internal_wall", "Internal wall")
    : null;

  // Residual-input checks mirror the pole unit: only values the ported math
  // actually consumes are validated, each on a normalized calculation copy —
  // authored rows and settings are never mutated. An explicit 0 override or
  // mortar gap is legitimate; negatives/malformed values hold the wall.
  const add = (kind, field, inventoryId, code, message) => issues.push({
    kind, index, componentId: wall?.component_id ?? wall?.id ?? null,
    field, inventoryId: inventoryId ?? null, code,
    message: `${kind === "internal_wall" ? "Internal wall" : "Wall"} ${index + 1}: ${message}.`,
  });
  const overrideCheck = (source, fields, kind, inventoryId) => {
    for (const [field, label] of fields) {
      const raw = source?.[field];
      if (raw === undefined || raw === null) continue;
      const value = wallPriceNumber(raw);
      if (value === null) {
        add(kind, field, inventoryId, field + "_unavailable",
          `record a finite, nonnegative ${label} override or clear it before repricing`);
      } else {
        source[field] = value;
      }
    }
  };
  const settingCheck = (key, label, positive) => {
    const value = positive
      ? wallPositiveSettingNumber(settings?.[key], WALL_SETTING_DEFAULTS[key])
      : wallSettingNumber(settings?.[key], WALL_SETTING_DEFAULTS[key]);
    if (value === null) {
      add("wall", key, wall?.materialId, "wall_setting_unavailable",
        `record a finite, ${positive ? "positive" : "nonnegative"} ${label} in Estimator Settings before repricing`);
    }
    return value;
  };
  const outerConcrete = wallMaterial?.wall_material_subtype === "concrete";
  const intConcrete = internalMaterial?.wall_material_subtype === "concrete";
  const calcWall = wall?.includeInternalWall && internalMaterial ? { ...wall } : wall;
  let mortarGapInches = WALL_MORTAR_GAP_DEFAULT;
  let internalMortarGapInches = WALL_MORTAR_GAP_DEFAULT;
  if (wallMaterial) {
    overrideCheck(wallMaterial, WALL_OUTER_OVERRIDE_FIELDS, "wall", wall?.materialId);
    settingCheck("wall_labor_rate", "wall labor rate");
    settingCheck("wall_minimum_charge", "wall minimum labor charge");
    // The production-rate setting is only consumed by unit-masonry paths — a
    // poured wall has no per-unit hours basis, so a malformed setting must not
    // hold a poured wall it cannot affect (unit fill still consumes it).
    if (!outerConcrete || (internalMaterial && !intConcrete)) {
      settingCheck("wall_labor_bricks_per_hour", "wall production rate", true);
    }
    if (!outerConcrete) {
      mortarGapInches = wallMortarGapNumber(wall?.mortarGapInches);
      if (mortarGapInches === null) {
        add("wall", "mortarGapInches", wall?.materialId, "wall_mortar_gap_unavailable",
          "record a finite, nonnegative mortar gap in inches before repricing");
      }
      overrideCheck(wallMaterial, WALL_OUTER_MORTAR_OVERRIDE_FIELDS, "wall", wall?.materialId);
    }
  }
  if (wall?.includeInternalWall && internalMaterial) {
    overrideCheck(calcWall, WALL_INTERNAL_OVERRIDE_FIELDS, "internal_wall", wall?.internalMaterialId);
    if (!intConcrete) {
      internalMortarGapInches = wallMortarGapNumber(wall?.internalMortarGapInches);
      if (internalMortarGapInches === null) {
        add("internal_wall", "internalMortarGapInches", wall?.internalMaterialId, "internal_wall_mortar_gap_unavailable",
          "record a finite, nonnegative mortar gap in inches before repricing");
      }
      overrideCheck(calcWall, WALL_INTERNAL_MORTAR_OVERRIDE_FIELDS, "internal_wall", wall?.internalMaterialId);
    }
  }
  if ((wallMaterial && !outerConcrete) || (internalMaterial && !intConcrete)) {
    settingCheck("wall_mortar_cost_per_bag", "mortar cost per bag");
  }

  return {
    issues, wallMaterial, internalMaterial, heightInches, internalWallHeightInches,
    wallShape: outline.shape, calcWall, mortarGapInches, internalMortarGapInches,
  };
}

export function foundationWallPricingIssues(wall, inventory = [], index = 0, settings = {}) {
  return wallPricing(wall, inventory, index, settings).issues;
}

export function foundationWallCatalogIssues(walls = [], inventory = [], settings = {}) {
  return walls.flatMap((wall, index) => foundationWallPricingIssues(wall, inventory, index, settings));
}

export function foundationWallBomRows(walls = [], inventory = [], wallPricing) {
  const out = [];
  const known = value => typeof value === "number" && Number.isFinite(value);
  // CMP-D03: the material quantity is labeled in its recorded basis — the
  // snapshot's materialQuantityUnit ("cy" placed volume on poured rows vs the
  // unit-masonry count). Snapshots pre-dating the flag keep the legacy
  // "units" vocabulary — the acknowledged number is never re-labeled.
  const quantity = (value, unit = "units") => known(value)
    ? `${value.toLocaleString(undefined, { maximumFractionDigits: 2 })} ${unit}` : "Not saved";
  const amount = value => known(value) ? value : "Not saved";
  const used = (qty, cost) => (known(qty) && qty > 0) || (known(cost) && cost !== 0);
  walls.forEach((wall, index) => {
    const costs = wall.calculatedCosts || {};
    const label = wall.name || `Wall ${index + 1}`;
    const saved = Array.isArray(wallPricing) && wallPricing[index]
      ? wallPricing[index].available === false
      : foundationWallPricingIssues(wall, inventory, index).length > 0;
    const nameOf = id => inventory.find(row => row.id === id)?.material_name || "Material";
    const add = (material, qty, cost) => out.push({ material, quantity: qty, cost: amount(cost), saved });
    if (saved || used(costs.totalBricks, costs.materialCost)) {
      add(saved ? `${label} — saved outer material` : `${label} — ${nameOf(wall.materialId)}`,
        quantity(costs.totalBricks, costs.materialQuantityUnit === "cy" ? "CY" : "units"), costs.materialCost);
    }
    if (known(costs.mortarCost) && costs.mortarCost !== 0) {
      add(`${label} — ${saved ? "saved mortar" : "mortar"}`, "—", costs.mortarCost);
    }
    const internalUsed = used(costs.internalTotalBricks, costs.internalMaterialCost);
    if ((saved && wall.includeInternalWall) || internalUsed) {
      add(saved ? `${label} — saved internal material` : `${label} — ${nameOf(wall.internalMaterialId)} (internal)`,
        quantity(costs.internalTotalBricks, costs.internalMaterialQuantityUnit === "cy" ? "CY" : "units"), costs.internalMaterialCost);
    }
    if (known(costs.internalMortarCost) && costs.internalMortarCost !== 0) {
      add(`${label} — ${saved ? "saved internal mortar" : "internal mortar"}`, "—", costs.internalMortarCost);
    }
  });
  return out;
}

// Runs the legacy wall math only when the selected material basis is available.
export function calcWalls(project, inventory, settings = {}, options = {}) {
  const walls = project.walls || [];
  const explicitSnapshot = options != null && Object.prototype.hasOwnProperty.call(options, "savedWalls");
  const savedWalls = Array.isArray(options?.savedWalls) ? options.savedWalls : [];
  const counts = rows => {
    const out = new Map();
    for (const row of rows) {
      const id = row?.component_id;
      if (assignedId(id)) out.set(id, (out.get(id) || 0) + 1);
    }
    return out;
  };
  const currentCounts = counts(walls), savedCounts = counts(savedWalls);
  const savedById = new Map(savedWalls.filter(row => assignedId(row?.component_id))
    .map(row => [row.component_id, row]));
  const held = wall => {
    const id = wall?.component_id;
    const acknowledged = explicitSnapshot
      ? assignedId(id) && currentCounts.get(id) === 1 && savedCounts.get(id) === 1
        ? savedById.get(id) : null
      : wall;
    const costs = acknowledged?.calculatedCosts;
    return {
      ...wall,
      calculatedCosts: costs && typeof costs === "object" && !Array.isArray(costs) ? { ...costs } : {},
    };
  };
  const results = walls.map((wall, index) => wallPricing(wall, inventory, index, settings));
  return {
    walls: results.map((check, index) => {
      const wall = walls[index];
      if (check.issues.length) return held(wall);
      const { wallMaterial, internalMaterial, heightInches, internalWallHeightInches, wallShape,
        calcWall, mortarGapInches, internalMortarGapInches } = check;
      const costs =
        calcWallCosts({
          wall: calcWall ?? wall,
          wallShape,
          wallMaterial,
          internalMaterial,
          includeInternalWall: wall.includeInternalWall,
          wallHeightInches: heightInches,
          internalWallHeightInches,
          mortarGapInches,
          internalMortarGapInches,
          settings,
        }) || {};
      return {
        ...wall,
        calculatedCosts: {
          // ?? keeps an accidental NaN visible instead of laundering it to $0.
          totalBricks: costs.finalBricks ?? 0,
          materialCost: costs.materialCost ?? 0,
          mortarCost: costs.mortarCost ?? 0,
          laborHours: costs.laborHours ?? 0,
          laborCost: costs.laborCost ?? 0,
          totalCost: costs.totalCost ?? 0,
          totalLinearInches: costs.totalLinearInches ?? 0,
          numCourses: costs.numCourses ?? 0,
          internalTotalBricks: costs.internalTotalBricks ?? 0,
          internalMaterialCost: costs.internalMaterialCost ?? 0,
          internalMortarCost: costs.internalMortarCost ?? 0,
          internalLaborCost: costs.internalLaborCost ?? 0,
          internalLaborHours: costs.internalLaborHours ?? 0,
          // CMP-D03: poured-concrete walls carry the quantity basis on the
          // snapshot ("cy" placed volume, vs the unit-masonry count) so saved
          // rows, BOM and Builder parts can label the quantity honestly. Unit
          // masonry is untouched — no extra keys on unchanged paths.
          ...(wallMaterial?.wall_material_subtype === "concrete" ? { materialQuantityUnit: "cy" } : {}),
          ...(wall.includeInternalWall && internalMaterial?.wall_material_subtype === "concrete"
            ? { internalMaterialQuantityUnit: "cy" } : {}),
        },
      };
    }),
    wallPricing: results.map((check) => ({ available: check.issues.length === 0, issues: check.issues })),
  };
}

import { foundationEquipmentCatalogIssues } from "./foundationEquipmentBindings";
import { foundationWallCapCatalogIssues } from "./wallCapCalculator";
import { foundationWallCatalogIssues } from "./wallCalculator";
// CMP-A08: the catalog price basis lives on the normalization boundary —
// finite, nonnegative; a recorded 0 is a deliberate free price, absent or
// malformed is unpriced (never laundered to 0 or guessed).
import { inventoryNonnegativeNumber } from "@/components/masterInventory/inventoryNormalization";

// ─── Catalog lifecycle + price classification (O-009 / CMP-A09) ────────────
//
// The catalog rows the estimator sees arrive through a filtered load
// (`show_in_foundation: true` on FoundationInventory, `is_active: true` on
// LaborServiceInventory) — except labor-service supplier rows, which are
// merged client-side AFTER the query and can still carry
// `show_in_foundation: false`, and any row a caller passes unfiltered. A
// project reference can therefore resolve four ways, previously lumped:
//   • the row is present and current            → usable,
//   • the row is present but marked INACTIVE    → was picked before
//     deactivation; the picker hides it now (was reported as nothing),
//   • the row is present but marked DELETED     → soft-deleted tombstone
//     still in the loaded list,
//   • the row is ABSENT                         → deleted or filtered out;
//     we cannot tell which from this list, so the issue says both.
// Price basis classifies the same way: a recorded finite nonnegative price
// is "priced" (0 = deliberately free), anything else is "unpriced" — the
// ported `|| 0` fallbacks laundered unpriced into a silent free.

const INACTIVE_STATUS_VALUES = new Set([
  "inactive", "disabled", "archived", "discontinued", "retired", "deactivated",
]);
const DELETED_STATUS_VALUES = new Set(["deleted", "removed", "purged"]);

// Row lifecycle class: "deleted" tombstones win over "inactive" flags; a row
// carrying neither is "active". Schemaless flags from every catalog source
// are honored — FoundationInventory's picker flag (`show_in_foundation`),
// LaborServiceInventory's `is_active`, and generic `active`/`archived`/
// `status`/`deleted_at` markers an import or admin surface may write.
export function foundationCatalogRowAvailability(row) {
  if (!row || typeof row !== "object") return "deleted";
  const status = typeof row.status === "string" ? row.status.trim().toLowerCase() : "";
  if (row.deleted === true || row.is_deleted === true || row.deleted_at != null
    || DELETED_STATUS_VALUES.has(status)) return "deleted";
  if (row.is_active === false || row.active === false
    || row.archived === true || row.is_archived === true || row.disabled === true
    || row.show_in_foundation === false || INACTIVE_STATUS_VALUES.has(status)) return "inactive";
  return "active";
}

// Consumed catalog price basis: "unpriced" (absent/malformed/negative — the
// boundary returns null), "free" (a recorded explicit 0), else "priced".
export function foundationCatalogPriceClass(value) {
  const number = inventoryNonnegativeNumber(value);
  if (number === null) return "unpriced";
  return number === 0 ? "free" : "priced";
}

// A custom override is "authored" exactly when the calculator consumes it —
// `value !== null && !== undefined` mirrors the calcItemCost `??` picks.
const authoredOverride = (value) => value !== undefined && value !== null;
// The item's `|| "#4"` / picker fallbacks treat every falsy value as
// unselected; mirror that (an authored blank string still defaults).
const authoredSelection = (value) => value !== undefined && value !== null && value !== "";

export function foundationItemCatalogIssues(item, inventory = [], index = 0) {
  const issues = [];
  const add = (field, id, code, message) => issues.push({
    kind: "foundation", index, componentId: item.component_id ?? null, field,
    inventoryId: id ?? null, code,
    message: `Foundation ${index + 1}: ${message}`,
  });
  const selected = id => id !== undefined && id !== null && id !== "";
  // Selected-id check: absent → unavailable (deleted or deactivated — the
  // loaded catalog can't tell them apart); found → type, then lifecycle,
  // then the consumed price basis. Deliberate free (recorded 0) never flags.
  const check = (field, types, label, { unassigned = null, priceBasis = null } = {}) => {
    const id = item[field];
    if (!selected(id)) {
      if (unassigned) add(field, null, "catalog_item_unassigned", unassigned);
      return;
    }
    const row = inventory.find(record => record.id === id);
    if (!row) {
      add(field, id, "catalog_item_unavailable",
        `${label} is unavailable — the catalog row may have been deleted or deactivated`);
      return;
    }
    if (!types.includes(row.material_type)) {
      add(field, id, "catalog_item_type_mismatch", `${label} is the wrong catalog type`);
      return;
    }
    const availability = foundationCatalogRowAvailability(row);
    if (availability !== "active") {
      add(field, id, availability === "deleted" ? "catalog_item_deleted" : "catalog_item_inactive",
        availability === "deleted"
          ? `${label} is marked deleted in the catalog — pick a replacement`
          : `${label} is inactive in the catalog — reactivate it or pick a replacement`);
      return;
    }
    const basis = priceBasis?.(row);
    if (basis && foundationCatalogPriceClass(row[basis]) === "unpriced") {
      add(field, id, "catalog_item_unpriced",
        `${label} has no recorded ${basis} — a missing price is not a free material`);
    }
  };
  // Concrete is consumed by every item: an unassigned selection rides the
  // first supplier's delivery catalog or prices material at $0, never an
  // authored free — flag it like the sibling pickers already do.
  check("selected_concrete_id", ["bagged_concrete", "concrete_service"], "the selected concrete catalog material", {
    unassigned: "select a concrete catalog material — unassigned concrete rides the first supplier's delivery mix or prices at $0",
    // Item-level bag pricing consumes cost_per_unit; a service row's mixes
    // and fees are the delivery scan's own checks, never duplicated here.
    priceBasis: row => (row.material_type === "bagged_concrete" && !authoredOverride(item.custom_concrete_cost_per_cy)
      ? "cost_per_unit" : null),
  });
  if (item.include_forming) check("selected_forming_id", ["forming_material"], "the selected forming catalog material", {
    // An authored custom rate replaces the catalog basis entirely; the row
    // is then consumed for nothing and unassigned/unpriced stay silent.
    unassigned: !authoredOverride(item.custom_forming_rate)
      ? "select a forming catalog material or record a custom forming rate"
      : null,
    priceBasis: row => (!authoredOverride(item.custom_forming_rate) ? "cost_per_unit" : null),
  });
  // Versioned items price steel through their explicit reinforcement_material
  // basis — a catalog basis needs exactly one current rebar-typed row; the
  // legacy rebar_size lookup below does not apply to them.
  if (item.reinforcement_calculation_version != null && item.reinforcement_calculation_version !== 1) {
    if (item.reinforcement_calculation_version === 2 && item.include_rebar && item.reinforcement_material?.kind === "catalog") {
      const id = item.reinforcement_material.inventory_id;
      const matches = selected(id) ? inventory.filter(row => row.id === id) : [];
      if (matches.length !== 1 || matches[0].material_type !== "rebar") {
        add("reinforcement_material.inventory_id", id,
          !selected(id) ? "catalog_item_unassigned" : matches.length > 1 ? "catalog_item_ambiguous" : "catalog_item_unavailable",
          !selected(id) ? "select a reinforcement catalog material"
            : matches.length > 1 ? "the selected reinforcement catalog ID is ambiguous; refresh the catalog"
            : "the selected reinforcement catalog material is unavailable — it may have been deleted or deactivated");
      } else {
        const availability = foundationCatalogRowAvailability(matches[0]);
        if (availability !== "active") {
          add("reinforcement_material.inventory_id", id,
            availability === "deleted" ? "catalog_item_deleted" : "catalog_item_inactive",
            availability === "deleted"
              ? "the selected reinforcement catalog material is marked deleted — pick a replacement"
              : "the selected reinforcement catalog material is inactive — reactivate it or pick a replacement");
        }
      }
    }
    return issues;
  }
  const manualRebar = hasFoundationCostSnapshot(item.custom_rebar_cost_per_ft) && item.custom_rebar_cost_per_ft >= 0;
  if (item.include_rebar && !manualRebar) {
    const field = item.foundation_type === "spread_foot" ? "rebar_size" : "pillar_rebar_size";
    const authoredSize = field === "rebar_size" ? item.rebar_size : item.pillar_rebar_size;
    // A pillar with no authored size silently consumes the catalog "#4"
    // default (the ported `pillar_rebar_size || '#4'` pick) — flag the
    // unassigned default whether or not a #4 row exists to consume.
    const defaulted = field === "pillar_rebar_size" && !authoredSize;
    const size = defaulted ? "#4" : authoredSize;
    const row = size ? inventory.find(record => record.material_type === "rebar" && record.rebar_size === size) : null;
    if (defaulted) {
      const rowState = row ? foundationCatalogRowAvailability(row) : null;
      add(field, row?.id ?? null, "catalog_item_unassigned_default", !row
        ? `no rebar size is selected and the catalog has no ${size} rebar default to consume — select a size`
        : rowState !== "active"
          ? `no rebar size is selected — the catalog ${size} default resolves to ${rowState === "inactive" ? "an inactive" : "a deleted"} row; pick a size explicitly`
          : `no rebar size is selected — the catalog ${size} default is consumed; pick a size explicitly`);
    } else if (!row) {
      add(field, null, size ? "catalog_item_unavailable" : "catalog_item_unassigned",
        size ? `rebar catalog size ${size} is unavailable — it may have been deleted or deactivated`
          : "select a rebar catalog size");
    } else {
      const availability = foundationCatalogRowAvailability(row);
      if (availability !== "active") {
        add(field, row.id, availability === "deleted" ? "catalog_item_deleted" : "catalog_item_inactive",
          availability === "deleted"
            ? `rebar catalog size ${size} is marked deleted — pick another size`
            : `rebar catalog size ${size} is inactive — reactivate it or pick another size`);
      } else if (!authoredOverride(item.custom_rebar_cost_per_ft)
        && foundationCatalogPriceClass(row.cost_per_unit) === "unpriced") {
        add(field, row.id, "catalog_item_unpriced",
          `rebar catalog size ${size} has no recorded cost_per_unit — a missing price is not a free material`);
      }
    }
  }
  return issues;
}

// Check catalog availability and the explicit wall-cap full-stock price basis.
export function foundationAssemblyCatalogIssues(project, inventory = []) {
  const issues = [];
  const check = (row, index, kind, field, label) => {
    const id = row[field];
    const assigned = (typeof id === "string" && id.trim() !== "")
      || (typeof id === "number" && Number.isFinite(id));
    if (!assigned) {
      issues.push({
        kind,
        index,
        componentId: row.component_id ?? row.id ?? null,
        field,
        inventoryId: null,
        code: "catalog_item_unassigned",
        message: `${label} ${index + 1}: select a catalog material.`,
      });
      return;
    }
    const match = inventory.find((record) => record.id === id);
    if (!match) {
      issues.push({
        kind,
        index,
        componentId: row.component_id ?? row.id ?? null,
        field,
        inventoryId: id,
        code: "catalog_item_unavailable",
        message: `${label} ${index + 1}: selected catalog material is unavailable — it may have been deleted or deactivated.`,
      });
      return;
    }
    const availability = foundationCatalogRowAvailability(match);
    if (availability !== "active") {
      issues.push({
        kind,
        index,
        componentId: row.component_id ?? row.id ?? null,
        field,
        inventoryId: id,
        code: availability === "deleted" ? "catalog_item_deleted" : "catalog_item_inactive",
        message: availability === "deleted"
          ? `${label} ${index + 1}: selected catalog material is marked deleted — pick a replacement.`
          : `${label} ${index + 1}: selected catalog material is inactive — reactivate it or pick a replacement.`,
      });
    }
  };
  for (const [index, pole] of (project?.poles || []).entries()) {
    check(pole, index, "pole", "pole_id", "Pole");
  }
  // Unassigned-default (CMP-A09): when the project names no concrete mix the
  // delivery scan silently consumes the first ready-mix supplier's catalog
  // '4000_ae' mix. Flag the unassigned default whenever a service supplier is
  // actually selected — the mix consumption itself stays the delivery scan's.
  if (!project?.project_concrete_type) {
    const firstServiceItem = (project?.items || []).find((item) => {
      const row = inventory.find((record) => record?.id === item?.selected_concrete_id);
      return row?.material_type === "concrete_service";
    });
    if (firstServiceItem) {
      issues.push({
        kind: "concrete_delivery",
        index: null,
        componentId: null,
        field: "project_concrete_type",
        inventoryId: firstServiceItem.selected_concrete_id ?? null,
        code: "catalog_item_unassigned_default",
        message: "Concrete delivery: no concrete mix is selected — the supplier's catalog default mix is consumed when concrete ships. Pick a mix explicitly.",
      });
    }
  }
  return [
    ...issues,
    ...foundationWallCatalogIssues(project?.walls || [], inventory),
    ...foundationWallCapCatalogIssues(project?.wall_caps || [], inventory),
    ...(project?.items || []).flatMap((item, index) => foundationItemCatalogIssues(item, inventory, index)),
    ...foundationEquipmentCatalogIssues(project?.selected_equipment || [], inventory),
  ];
}

// ─── Advisory classification audit (O-009 / CMP-A09) ────────────────────────
//
// Non-blocking mirror of the item scan: every catalog basis the item can
// consume, classified so downstream surfaces keep deliberate free ($0),
// unpriced (missing), implicit defaults, and inactive/deleted rows distinct
// instead of lumping them under "unavailable". Nothing here gates pricing —
// the blocking flags live in foundationItemCatalogIssues above.
export function foundationItemCatalogAudit(item, inventory = [], index = 0) {
  const record = item ?? {};
  const audit = [];
  const emit = (field, inventoryId, selection, availability, priceClass) => audit.push({
    kind: "foundation", index, componentId: record.component_id ?? null,
    field, inventoryId: inventoryId ?? null, selection, availability, priceClass,
  });
  const auditId = (field, { overrideAuthored = false, priceBasis = null, unconsumedClass = "unchecked" } = {}) => {
    const id = record[field];
    if (!authoredSelection(id)) {
      emit(field, null, "unassigned", "unassigned", overrideAuthored ? "override" : unconsumedClass);
      return;
    }
    const row = inventory.find((candidate) => candidate.id === id);
    if (!row) {
      emit(field, id, "authored", "missing", overrideAuthored ? "override" : unconsumedClass);
      return;
    }
    const availability = foundationCatalogRowAvailability(row);
    const basis = priceBasis?.(row);
    emit(field, id, "authored", availability,
      overrideAuthored ? "override"
        : basis ? foundationCatalogPriceClass(row[basis]) : unconsumedClass);
  };
  auditId("selected_concrete_id", {
    overrideAuthored: authoredOverride(record.custom_concrete_cost_per_cy),
    priceBasis: (row) => (row.material_type === "bagged_concrete" ? "cost_per_unit" : null),
    unconsumedClass: "deferred", // ready-mix prices ship through the delivery scan's mix/admix/fee checks
  });
  if (record.include_forming) {
    auditId("selected_forming_id", {
      overrideAuthored: authoredOverride(record.custom_forming_rate),
      priceBasis: () => "cost_per_unit",
      unconsumedClass: "unconsumed", // a missing/unassigned forming row consumes no catalog basis
    });
  }
  if (record.reinforcement_calculation_version != null && record.reinforcement_calculation_version !== 1) {
    if (record.reinforcement_calculation_version === 2 && record.include_rebar
      && record.reinforcement_material?.kind === "catalog") {
      auditId("reinforcement_material.inventory_id", { unconsumedClass: "deferred" });
    }
    return audit;
  }
  const manualRebar = hasFoundationCostSnapshot(record.custom_rebar_cost_per_ft) && record.custom_rebar_cost_per_ft >= 0;
  if (record.include_rebar && !manualRebar) {
    const field = record.foundation_type === "spread_foot" ? "rebar_size" : "pillar_rebar_size";
    const authoredSize = field === "rebar_size" ? record.rebar_size : record.pillar_rebar_size;
    const defaulted = field === "pillar_rebar_size" && !authoredSize;
    const size = defaulted ? "#4" : authoredSize;
    if (!size) {
      emit(field, null, "unassigned", "unassigned",
        authoredOverride(record.custom_rebar_cost_per_ft) ? "override" : "unconsumed");
    } else {
      const row = inventory.find((candidate) => candidate.material_type === "rebar" && candidate.rebar_size === size);
      emit(field, row?.id ?? null, defaulted ? "defaulted" : "authored",
        row ? foundationCatalogRowAvailability(row) : "missing",
        authoredOverride(record.custom_rebar_cost_per_ft) ? "override"
          : row ? foundationCatalogPriceClass(row.cost_per_unit) : "unconsumed");
    }
  }
  return audit;
}

// A missing snapshot is not evidence of a free material.
export function hasFoundationCostSnapshot(value) {
  return typeof value === "number" && Number.isFinite(value);
}
